  r.pl_forces = Array.isArray(r.pl_forces) ? r.pl_forces : []; (s.forces || []).forEach((f) => { if (ORG[f] && r.pl_forces.indexOf(ORG[f]._id) < 0) { r.pl_forces.push(ORG[f]._id); filled.push('กองกำลัง ' + f.toUpperCase()); } });
  r.leaders = Array.isArray(r.leaders) ? r.leaders : []; let nl = 0;
  (s.leaders || []).forEach((l) => { const L = leaderOf(l); const hit = r.leaders.find((x) => (L.pref && x.pref === L.pref) || nk(x.name) === nk(L.name) || (L.name_en && nk(x.name) === nk(L.name_en)));
    if (hit) { ['title', 'role', 'pos', 'nat', 'photo', 'name_en'].forEach((k) => { if (!hit[k] && L[k]) hit[k] = L[k]; }); if (!hit.pref && L.pref) hit.pref = L.pref; }
    else { r.leaders.push(L); nl++; } });
  if (nl) filled.push('บุคคล +' + nl);
